precision highp float;

varying vec2 vTexCoord;

uniform vec2 u_resolution;
uniform int u_numOperations;
uniform int u_operationTypes[30];
uniform float u_params1[30];
uniform float u_params2[30];
uniform float u_params3[30];
uniform float u_params4[30];

float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = smoothstep(0.0,1.0,fract(st));
    float a = fract(sin(dot(i, vec2(12.9898, 78.233))) * 43758.5453);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(12.9898, 78.233))) * 43758.5453);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(12.9898, 78.233))) * 43758.5453);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 applyOperation(int type, vec2 uv, float param1, float param2, float param3, float param4, vec3 currentColor) {
    float aspect = u_resolution.x / u_resolution.y;
    float scaleFactor = 3.0;
    vec2 mappedUV = uv * scaleFactor;

    if (type == 0) {
        float a = param1; // Scale X
        float b = param2; // Scale Y
        float c = param3; // Translate X
        float d = param4; // Translate Y
        vec2 newUV = vec2(uv.x * a + c, uv.y * b + d);
        return vec3(newUV, 0.0);
    } else if (type == 1) {
      return vec3(-uv.x * param1, uv.y * param2, 0.0);
    } else if (type == 2) {
        return vec3(uv.x * param1, -uv.y * param2, 0.0);
    } else if (type == 3) {
      float dist = length(uv);
      //modified invert circle logic
       float modifiedParam = 0.001 + (1.0 - param1) * 0.999 ; // Invert the parameter range

        return vec3(uv / (dist * dist * modifiedParam), 0.0);

    } else if (type == 4) {
      float angle = atan(uv.y, uv.x) + param1;
      float radius = length(uv);
      return vec3(radius * cos(angle), radius * sin(angle), 0.0);
    } else if (type == 5) {
        float triX = mod(mappedUV.x, 1.0);
        float triY = mod(mappedUV.y, 0.8660254);
        vec2 offset = vec2(0.0);
         if (triY > 0.57735 * triX) {
            if (triY > -0.57735 * triX + 0.8660254) {
            } else {
                offset = vec2(0.5 * param1, 0.288675 * param2);
            }
        } else {
            offset = vec2(0.5 * param1, -0.288675 * param2);
        }
        return vec3(mappedUV.x + offset.x, mappedUV.y + offset.y, 0.0);
    } else if (type == 6) {
        float r = fract(currentColor.r + param1);
        float g = fract(currentColor.g + param2);
        float b = fract(currentColor.b + param3);
        return vec3(r, g, b);
    } else if (type == 7) {
        return currentColor + vec3(param1, param2, param3);
    } else if (type == 8) {
        return currentColor * vec3(param1, param2, param3);
    } else if (type == 9) {
        return vec3(currentColor.r == 0.0 ? 0.0 : mod(currentColor.r, param1), currentColor.g == 0.0 ? 0.0 : mod(currentColor.g, param2), currentColor.b == 0.0 ? 0.0 : mod(currentColor.b, param3));
    } else if (type == 10) {
        return abs(currentColor) * vec3(param1, param2, 0.0);
    } else if (type == 11) {
        return vec3(sin(currentColor.r * param1), sin(currentColor.g * param2), sin(currentColor.b * param3));
    } else if (type == 12) {
        return vec3(cos(currentColor.r * param1), cos(currentColor.g * param2), cos(currentColor.b * param3));
    } else if (type == 13) {
        return vec3(tan(currentColor.r * param1), tan(currentColor.g * param2), tan(currentColor.b * param3));
    } else if (type == 14) {
         vec3 noiseValue = vec3(noise(mappedUV * param1), noise(mappedUV * param2), noise(mappedUV*param3));
         return mix(currentColor, noiseValue, param4);
    } else if (type == 15) {
         float gradientValue = mappedUV.x * param1;
         return mix(currentColor,vec3(gradientValue, gradientValue, gradientValue),param4);
      } else if (type == 16) {
          float gradientValue = mappedUV.y * param1;
           return mix(currentColor,vec3(gradientValue, gradientValue, gradientValue),param4);
      } else if (type == 17) {
          float r = length(mappedUV);
           return mix(currentColor, vec3(r * param1, r * param2, r * param3), param4);
      } else if (type == 18) {
          float angle = atan(mappedUV.y, mappedUV.x);
        return  mix(currentColor, vec3(angle * param1, angle * param2, angle * param3), param4);
      } else if (type == 19) {
          return mix(currentColor, vec3(param1, param2, param3), param4);
      } else if (type == 20) {
          float contrast = param1;
          vec3 avgColor = vec3(0.2126, 0.7152, 0.0722);
          return ((currentColor - avgColor) * contrast + avgColor);
      } else if (type == 21) {
          float sat = param1;
          vec3 grayScale = vec3(dot(currentColor, vec3(0.299, 0.587, 0.114)));
          return mix(grayScale, currentColor, sat);
      } else if (type == 22) {
          return clamp(currentColor * param1, vec3(0.0), vec3(1.0));
      }  else if (type == 23) {
        return mix(vec3(0.5),currentColor,param1);
      } else if (type == 24) {
            float r = length(mappedUV);
          float angle = atan(mappedUV.y, mappedUV.x);

          return mix(currentColor, vec3(r * cos(angle) * param1, r * sin(angle) * param2, r * param3), param4);
        }

    return currentColor;
}


