}


    // Helper function to check if an opName is a transform operation
function isTransform(opName) {
    return baseOperationNames.includes(opName);
}

// Helper function to check if an opName is a color effect operation
function isColorEffect(opName) {
    return effectOperationNames.includes(opName) && !['noise', 'gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(opName);
}

// Helper function to check if an opName is a gradient or noise operation
function isGradientOrNoise(opName) {
    return ['noise', 'gradientX', 'gradientY', 'gradientRadial', 'gradientAngular'].includes(opName);
}

// Helper function for weighted random selection
function getWeightedRandom(items, weights) {
    let totalWeight = weights.reduce((acc, weight) => acc + weight, 0);
    let randomNumber = Math.random() * totalWeight;
    for (let i = 0; i < items.length; i++) {
        randomNumber -= weights[i];
        if (randomNumber <= 0) {
            return items[i];
        }
    }
    return items[items.length - 1]; 
}

function isBadGradientRadial(param1, param2, param3) {
